-- ============================================================
-- SIMULACRO FINAL — 45 preguntas reales del ICFES (Tabla 17)
-- ============================================================
-- Reemplaza por completo el quiz viejo de 8 preguntas del Módulo 8.
-- Distribución oficial: Parte 1=5, Parte 2=5, Parte 3=5, Parte 4=8,
-- Parte 5=7, Parte 6=5, Parte 7=10 (total 45), cada parte en su
-- formato real: avisos (4 op.), banco de 8 palabras, diálogos (3 op.),
-- texto con espacios básico (4 op.), lectura literal (3 op.), lectura
-- inferencial (4 op.), texto con espacios avanzado (4 op.).
--
-- Requiere haber corrido antes: seed-pre-icfes-modules.sql,
-- quiz-content-pre-icfes.sql (crea el quiz viejo, que este script
-- reemplaza). Mantiene el mismo régimen de examen de certificación:
-- 75/100 para pasar, 3 intentos, 24h de espera entre intentos.
-- Seguro de correr varias veces.
-- ============================================================


delete from public.quiz_questions
where quiz_id in (
  select qz.id from public.quizzes qz
  join public.modules m on m.id = qz.module_id
  join public.courses c on c.id = m.course_id
  where c.slug = 'pre-icfes' and m.title = 'Simulacro final' and qz.stage = 'main'
);

insert into public.quizzes (module_id, title, passing_score, is_final, max_attempts, cooldown_hours, stage)
select m.id, 'Simulacro final — Examen de certificación (45 preguntas)', 75, true, 3, 24, 'main'
from public.modules m join public.courses c on c.id = m.course_id
where c.slug = 'pre-icfes' and m.title = 'Simulacro final'
on conflict (module_id, stage) do update set title = excluded.title, passing_score = excluded.passing_score, is_final = excluded.is_final, max_attempts = excluded.max_attempts, cooldown_hours = excluded.cooldown_hours;

insert into public.quiz_questions (quiz_id, order_index, prompt)
select qz.id, v.order_index, v.prompt
from public.quizzes qz join public.modules m on m.id = qz.module_id join public.courses c on c.id = m.course_id
cross join (values
  (0, '<div class=''sim-part-tag''>Parte 1 de 7 — Avisos y vocabulario</div><p>Ves el aviso <strong>"EMPLOYEES MUST WASH HANDS BEFORE RETURNING TO WORK"</strong> en el baño de un restaurante. ¿Qué exige este aviso?</p>'),
  (1, '<div class=''sim-part-tag''>Parte 1 de 7 — Avisos y vocabulario</div><p>Un letrero en un aeropuerto dice <strong>"FLIGHT DELAYED — NEW BOARDING TIME: 3:45 PM"</strong>. ¿Qué información da este aviso?</p>'),
  (2, '<div class=''sim-part-tag''>Parte 1 de 7 — Avisos y vocabulario</div><p>En la entrada de una piscina ves <strong>"NO DIVING — SHALLOW WATER"</strong>. ¿Qué NO deberías hacer?</p>'),
  (3, '<div class=''sim-part-tag''>Parte 1 de 7 — Avisos y vocabulario</div><p>Un aviso en una biblioteca dice <strong>"SILENCE PLEASE — STUDY AREA"</strong>. ¿Qué comportamiento pide este aviso?</p>'),
  (4, '<div class=''sim-part-tag''>Parte 1 de 7 — Avisos y vocabulario</div><p>Ves <strong>"OUT OF ORDER — USE OTHER ENTRANCE"</strong> pegado en una puerta automática de un centro comercial. ¿Qué deberías hacer?</p>'),
  (5, '<div class=''sim-part-tag''>Parte 2 de 7 — Relación de enunciados (banco de 8 palabras)</div><p style=''font-size:13px;color:var(--muted);margin-bottom:8px;''>Banco (A–H): menu, brochure, invoice, schedule, voucher, itinerary, receipt, certificate — cada palabra se usa una sola vez, 3 quedan sin usar.</p><p><strong>Enunciado:</strong> "This document lists the exact times of your flights and hotel stays during a trip."</p>'),
  (6, '<div class=''sim-part-tag''>Parte 2 de 7 — Relación de enunciados (banco de 8 palabras)</div><p style=''font-size:13px;color:var(--muted);margin-bottom:8px;''>Banco (A–H): menu, brochure, invoice, schedule, voucher, itinerary, receipt, certificate — cada palabra se usa una sola vez, 3 quedan sin usar.</p><p><strong>Enunciado:</strong> "Restaurants give you this list to choose your food and drinks."</p>'),
  (7, '<div class=''sim-part-tag''>Parte 2 de 7 — Relación de enunciados (banco de 8 palabras)</div><p style=''font-size:13px;color:var(--muted);margin-bottom:8px;''>Banco (A–H): menu, brochure, invoice, schedule, voucher, itinerary, receipt, certificate — cada palabra se usa una sola vez, 3 quedan sin usar.</p><p><strong>Enunciado:</strong> "You receive this small paper as proof after you have already paid for something."</p>'),
  (8, '<div class=''sim-part-tag''>Parte 2 de 7 — Relación de enunciados (banco de 8 palabras)</div><p style=''font-size:13px;color:var(--muted);margin-bottom:8px;''>Banco (A–H): menu, brochure, invoice, schedule, voucher, itinerary, receipt, certificate — cada palabra se usa una sola vez, 3 quedan sin usar.</p><p><strong>Enunciado:</strong> "A travel agency gives you this paper that you can exchange for a free hotel night or a discount."</p>'),
  (9, '<div class=''sim-part-tag''>Parte 2 de 7 — Relación de enunciados (banco de 8 palabras)</div><p style=''font-size:13px;color:var(--muted);margin-bottom:8px;''>Banco (A–H): menu, brochure, invoice, schedule, voucher, itinerary, receipt, certificate — cada palabra se usa una sola vez, 3 quedan sin usar.</p><p><strong>Enunciado:</strong> "Schools give you this official document to prove you finished a course."</p>'),
  (10, '<div class=''sim-part-tag''>Parte 3 de 7 — Diálogos y coherencia conversacional</div><p>"Do you want to join us for lunch?"</p>'),
  (11, '<div class=''sim-part-tag''>Parte 3 de 7 — Diálogos y coherencia conversacional</div><p>"I can''t find my keys anywhere."</p>'),
  (12, '<div class=''sim-part-tag''>Parte 3 de 7 — Diálogos y coherencia conversacional</div><p>"You look tired today."</p>'),
  (13, '<div class=''sim-part-tag''>Parte 3 de 7 — Diálogos y coherencia conversacional</div><p>"What''s your favorite subject at school?"</p>'),
  (14, '<div class=''sim-part-tag''>Parte 3 de 7 — Diálogos y coherencia conversacional</div><p>"Could you turn down the music, please?"</p>'),
  (15, '<div class=''sim-part-tag''>Parte 4 de 7 — Texto con espacios (nivel básico)</div><div class=''cloze-passage''>Last weekend, my brother and I went <mark>___(1)___</mark> our grandmother''s house in the countryside. We arrived ___(2)___ ten in the morning and helped her ___(3)___ the garden. She showed us how ___(4)___ plant tomatoes and beans. At noon, we had lunch together and talked about ___(5)___ childhood memories. In the afternoon, my brother played football with ___(6)___ friends from the village while I read a book ___(7)___ the porch. Before we left, our grandmother gave each of us a small basket ___(8)___ fresh vegetables.</div><p style=''margin-top:8px;''><strong>Elige la opción correcta para el espacio (1).</strong></p>'),
  (16, '<div class=''sim-part-tag''>Parte 4 de 7 — Texto con espacios (nivel básico)</div><div class=''cloze-passage''>Last weekend, my brother and I went ___(1)___ our grandmother''s house in the countryside. We arrived <mark>___(2)___</mark> ten in the morning and helped her ___(3)___ the garden. She showed us how ___(4)___ plant tomatoes and beans. At noon, we had lunch together and talked about ___(5)___ childhood memories. In the afternoon, my brother played football with ___(6)___ friends from the village while I read a book ___(7)___ the porch. Before we left, our grandmother gave each of us a small basket ___(8)___ fresh vegetables.</div><p style=''margin-top:8px;''><strong>Elige la opción correcta para el espacio (2).</strong></p>'),
  (17, '<div class=''sim-part-tag''>Parte 4 de 7 — Texto con espacios (nivel básico)</div><div class=''cloze-passage''>Last weekend, my brother and I went ___(1)___ our grandmother''s house in the countryside. We arrived ___(2)___ ten in the morning and helped her <mark>___(3)___</mark> the garden. She showed us how ___(4)___ plant tomatoes and beans. At noon, we had lunch together and talked about ___(5)___ childhood memories. In the afternoon, my brother played football with ___(6)___ friends from the village while I read a book ___(7)___ the porch. Before we left, our grandmother gave each of us a small basket ___(8)___ fresh vegetables.</div><p style=''margin-top:8px;''><strong>Elige la opción correcta para el espacio (3).</strong></p>'),
