insert into public.quiz_choices (question_id, order_index, choice_text, is_correct, feedback)
select qq.id, v.order_index, v.choice_text, v.is_correct, v.feedback
from public.quiz_questions qq join public.quizzes qz on qz.id=qq.quiz_id join public.modules m on m.id=qz.module_id join public.courses c on c.id=m.course_id
cross join (values (0,'Que los empleados se laven las manos antes de volver a trabajar',true,'Correcto: el aviso exige higiene antes de regresar al trabajo.'),(1,'Que los empleados usen guantes todo el tiempo',false,'El aviso no menciona guantes.'),(2,'Que los clientes se laven las manos antes de comer',false,'El aviso está dirigido a ''employees'', no a clientes.'),(3,'Que el baño está cerrado por mantenimiento',false,'No hay ninguna mención de cierre en el aviso.')) as v(order_index,choice_text,is_correct,feedback)
where c.slug='pre-icfes' and m.title='Simulacro final' and qq.order_index=0 and exists(select 1 from public.quizzes qz2 where qz2.id=qq.quiz_id and qz2.stage='main')
on conflict (question_id, order_index) do nothing;

